sysauto_script.script:
/**
 * Monthly Warehouse Demand Forecast Generator
 *
 * Runs on the 1st of every month at 2:00 AM.
 * Generates warehouse-aware demand forecasts for ALL active material+warehouse
 * combinations using the DemandForecastEngine.
 *
 * Each material at each warehouse gets its own independent forecast.
 * Demand from Hyderabad, Chennai, and Bangalore is NEVER mixed.
 *
 * Creates:
 *   - Forecast records in x_2056099_indust_0_demand_forecast
 *   - Inventory alerts for projected shortages (reorder_required)
 *   - Inventory alerts for safety stock review signals (below_safety_stock)
 *
 * SAFETY: This script NEVER modifies safety stock levels or inventory.
 * It only creates forecast records and alerts.
 */
(function () {
    try {
        gs.info('[DemandForecast] Monthly warehouse demand forecast generation starting...');

        var engine = new DemandForecastEngine();
        var summary = engine.generateAllForecasts();

        gs.info('[DemandForecast] Forecast generation complete. ' +
            'Total: ' + summary.total +
            ', Success: ' + summary.success +
            ', Failed: ' + summary.failed);

        if (summary.failed > 0) {
            gs.warn('[DemandForecast] ' + summary.failed + ' forecasts failed. Errors: ' +
                summary.errors.slice(0, 5).join('; '));
        }

    } catch (e) {
        gs.error('[DemandForecast] Monthly forecast generation failed: ' + e.message);
    }
})();
